/**
 * The third-party licence list behind the About card (release spec section 9).
 * `ui/src/content/licences.json` is generated by
 * `cargo run -p release-tools -- licences`; never edit it by hand.
 */

export type LicencePackage = {
  name: string
  version: string
  /** The licence expression as the package declares it. */
  licence: string
  /** `rust` for a crate compiled into the app, `ui` for an interface package. */
  ecosystem: 'rust' | 'ui'
  /** Indexes into `LicenceList.texts`: identical texts are stored once. */
  texts: number[]
}

export type LicenceList = {
  packages: LicencePackage[]
  texts: string[]
}

export function parseLicences(json: string): LicenceList {
  return JSON.parse(json) as LicenceList
}

/**
 * The update channel shown next to the version: edge for a prerelease build,
 * stable otherwise (the channel default, spec ruling 8).
 */
export function channelOf(version: string): 'edge' | 'stable' {
  return version.includes('-') ? 'edge' : 'stable'
}
